import os
from openai import OpenAI


def get_required_env(name: str) -> str:
    value = os.getenv(name)
    if value is None or not value.strip():
        raise RuntimeError(f"Missing required environment variable: {name}")
    return value.strip()


def extract_message_text(response) -> str:
    choices = getattr(response, "choices", None)
    if not choices:
        raise RuntimeError("The API response did not include any choices.")
    message = getattr(choices[0], "message", None)
    if message is None:
        raise RuntimeError("The first choice did not include a message.")
    content = getattr(message, "content", None)
    if isinstance(content, str) and content.strip():
        return content
    if isinstance(content, list):
        text_parts = []
        for item in content:
            if isinstance(item, dict):
                if item.get("type") == "text" and isinstance(item.get("text"), str):
                    text_parts.append(item["text"])
            else:
                item_type = getattr(item, "type", None)
                item_text = getattr(item, "text", None)
                if item_type == "text" and isinstance(item_text, str):
                    text_parts.append(item_text)
        text = "".join(text_parts).strip()
        if text:
            return text
    raise RuntimeError("The API response did not include readable message content.")


def main() -> None:
    api_key = get_required_env("BIGMODEL_API_KEY")
    client = OpenAI(api_key=api_key, base_url="")
    try:
        response = client.chat.completions.create(
            model="glm-5.3",
            messages=[
                {
                    "role": "system",
                    "content": "You are a helpful assistant."
                },
                {
                    "role": "user",
                    "content": "Hello! Please summarize the key integration settings for GLM-5.3."
                }
            ],
            max_tokens=4096
        )
        print(extract_message_text(response))
    except Exception as exc:
        raise RuntimeError(f"GLM-5.3 request failed: {exc}") from exc


if __name__ == "__main__":
    main()
